async show(): Promise<void> {
  if (this._config.inline) {
    return // Inline calendars are always visible
  }

  if (!this._calendar || isDisabled(this._element) || this._isShown) {
    return
  }

  const showEvent = EventHandler.trigger(this._element, EVENT_SHOW)
  if (showEvent.defaultPrevented) {
    return
  }

  this._calendar.show()
  this._isShown = true

  // Move focus to the calendar for popup mode
  const mainElement = this._calendar.context.mainElement
  if (mainElement) {
    mainElement.setAttribute('tabindex', '-1')
    mainElement.focus()
  }

  EventHandler.trigger(this._element, EVENT_SHOWN)
}

async hide(): Promise<void> {
  if (this._config.inline) {
    return // Inline calendars are always visible
  }

  if (!this._calendar || !this._isShown) {
    return
  }

  const hideEvent = EventHandler.trigger(this._element, EVENT_HIDE)
  if (hideEvent.defaultPrevented) {
    return
  }

  this._calendar.hide()
  this._isShown = false

  // Remove tabindex from the main element
  const mainElement = this._calendar?.context?.mainElement
  if (mainElement) {
    mainElement.removeAttribute('tabindex')
  }

  EventHandler.trigger(this._element, EVENT_HIDDEN)
}
